  CONSTRAINT `fk_smc_song` FOREIGN KEY (`song_id`) REFERENCES `songs` (`song_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_smc_conf` CHECK ((((`action` = _utf8mb4'ADD') and (`confidence` > 0) and (`confidence` <= 1)) or ((`action` = _utf8mb4'REMOVE') and (`confidence` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `song_mood_ratings` (
  `user_id` int unsigned NOT NULL,
  `song_id` int unsigned NOT NULL,
  `mood_id` smallint unsigned NOT NULL,
  `match_percentage` decimal(5,2) NOT NULL,
  `review_text` varchar(280) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`,`song_id`,`mood_id`),
  KEY `idx_smr_song_mood` (`song_id`,`mood_id`,`match_percentage`),
