  CONSTRAINT `fk_smr_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_smr_pct` CHECK (((`match_percentage` >= 0) and (`match_percentage` <= 100))),
